head.b:skin:
*, *::before, *::after { box-sizing:border-box; }
html { margin:0; padding:0; scroll-behavior:smooth; -webkit-text-size-adjust:100%; }
body { margin:0; padding:0; font-family:'Cairo',system-ui,sans-serif; background:#f7f9fa; color:#1e293b; direction:rtl; text-align:right; line-height:1.8; font-size:16px; overflow-x:hidden; transition:background .3s,color .3s; }
img { max-width:100%; height:auto; display:block; border:0; }
a { color:#1a5490; text-decoration:none; transition:color .2s ease; }
a:hover { color:#0e3a5c; }
ul, ol { list-style:none; margin:0; padding:0; }
h1, h2, h3, h4 { margin:0 0 12px; line-height:1.4; font-weight:800; color:#0e3a5c; }
p { margin:0 0 14px; }
button, input, textarea, select { font-family:inherit; }
.container { max-width:1200px; margin:0 auto; padding:0 20px; width:100%; }

/* ═══ HEADER — COLORED ═══ */
.site-header { background:linear-gradient(135deg,#0e3a5c 0%,#1a5490 55%,#2d7a3e 100%); box-shadow:0 2px 16px rgba(14,58,92,.35); position:sticky; top:0; z-index:999; }
.header-inner { display:flex; align-items:center; justify-content:space-between; gap:20px; padding:14px 0; flex-wrap:wrap; }
.brand { display:flex; align-items:center; gap:14px; }
.brand-logo-img { width:60px; height:60px; border-radius:12px; object-fit:cover; box-shadow:0 4px 14px rgba(0,0,0,.35); flex-shrink:0; background:#fff; }
.brand-text { display:flex; flex-direction:column; line-height:1.25; }
.brand-title { font-size:22px; font-weight:900; color:#fff !important; margin:0; text-shadow:0 2px 6px rgba(0,0,0,.25); }
.brand-subtitle { font-size:12px; color:rgba(255,255,255,.85); font-weight:500; }
.main-nav { flex:1; margin-inline-start:20px; }
.nav-list { display:flex; align-items:center; gap:2px; flex-wrap:wrap; }
.nav-list a { display:block; padding:10px 14px; border-radius:8px; color:#fff !important; font-weight:600; font-size:14.5px; white-space:nowrap; }
.nav-list a:hover { background:rgba(255,255,255,.15); color:#fff !important; }
.header-tools { display:flex; align-items:center; gap:10px; }
.theme-toggle { background:rgba(255,255,255,.15); border:1px solid rgba(255,255,255,.3); width:44px; height:44px; border-radius:10px; cursor:pointer; font-size:20px; display:flex; align-items:center; justify-content:center; transition:all .2s; flex-shrink:0; color:#fff; }
.theme-toggle:hover { background:rgba(255,255,255,.28); }
.search-form { display:flex; align-items:center; background:rgba(255,255,255,.95); border:1px solid rgba(255,255,255,.4); border-radius:24px; padding:2px; }
.search-form:focus-within { background:#fff; box-shadow:0 0 0 3px rgba(255,255,255,.3); }
.search-form input { border:0; outline:0; background:transparent; padding:8px 14px; width:180px; font-size:14px; color:#1e293b; }
.search-form input::placeholder { color:#64748b; }
.search-form button { border:0; cursor:pointer; background:#0e3a5c; color:#fff; font-weight:700; padding:8px 16px; border-radius:20px; font-size:13px; }
.search-form button:hover { background:#08293f; }
.nav-toggle { display:none; background:rgba(255,255,255,.15); border:1px solid rgba(255,255,255,.3); color:#fff; width:44px; height:44px; border-radius:10px; cursor:pointer; font-size:22px; font-weight:700; flex-shrink:0; }

.section { padding:50px 0; }
.section-alt { background:#fff; }
.section-head { display:flex; align-items:center; justify-content:space-between; gap:16px; flex-wrap:wrap; margin-bottom:32px; padding-bottom:16px; border-bottom:2px solid #e2e8f0; }
.section-title { font-size:26px; font-weight:800; color:#0e3a5c; margin:0; display:flex; align-items:center; gap:12px; }
.section-title::before { content:''; width:6px; height:30px; border-radius:4px; background:linear-gradient(180deg,#1a5490,#2d7a3e); display:inline-block; flex-shrink:0; }
.section-more { font-size:14px; font-weight:700; color:#1a5490; background:rgba(26,84,144,.08); padding:8px 18px; border-radius:20px; }
.section-more:hover { background:#1a5490; color:#fff; }

.news-magazine { display:flex; flex-direction:column; gap:20px; }
.news-top { display:grid; grid-template-columns:2fr 1fr; gap:16px; height:480px; }
.news-side-stack { display:grid; grid-template-rows:1fr 1fr; gap:16px; }
.news-grid-4 { display:grid; grid-template-columns:repeat(4, 1fr); gap:16px; }
.news-item { position:relative; display:block; overflow:hidden; border-radius:12px; background:#0e3a5c; color:#fff !important; box-shadow:0 4px 14px rgba(14,58,92,.15); transition:transform .3s, box-shadow .3s; cursor:pointer; }
.news-item:hover { transform:translateY(-3px); box-shadow:0 12px 30px rgba(14,58,92,.28); }
.news-item-bg { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; transition:transform .5s; }
.news-item:hover .news-item-bg { transform:scale(1.06); }
.news-item-overlay { position:absolute; inset:0; background:linear-gradient(to top, rgba(0,0,0,.85) 0%, rgba(0,0,0,.55) 35%, rgba(0,0,0,.15) 65%, rgba(0,0,0,0) 100%); display:flex; flex-direction:column; justify-content:flex-end; padding:16px 18px; z-index:2; }
.news-item-title { color:#fff !important; font-size:18px; font-weight:800; line-height:1.5; margin:0 0 8px; text-shadow:0 2px 6px rgba(0,0,0,.6); display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; }
.news-item-date { display:inline-flex; align-items:center; gap:6px; font-size:12.5px; font-weight:600; color:#e2e8f0; background:rgba(0,0,0,.45); padding:4px 10px; border-radius:14px; align-self:flex-start; backdrop-filter:blur(4px); }
.news-hero .news-item-title { font-size:26px; }
.news-hero .news-item-overlay { padding:24px 26px; }
.news-side .news-item-title { font-size:16px; }
.news-grid-4 .news-item { aspect-ratio:16/11; }
.news-grid-4 .news-item-title { font-size:15px; }
.news-grid-4 .news-item-overlay { padding:14px 16px; }
.news-item.no-image { background:linear-gradient(135deg,#0e3a5c,#2d7a3e); }

.loading, .empty-msg { text-align:center; color:#64748b; padding:40px 20px; font-size:15px; background:#fff; border-radius:14px; border:1px solid #e2e8f0; }

.cards-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:24px; }
.card { background:#fff; border-radius:14px; overflow:hidden; box-shadow:0 4px 20px rgba(14,58,92,.08); display:flex; flex-direction:column; border:1px solid #e2e8f0; }
.card-thumb { position:relative; display:block; width:100%; aspect-ratio:16/9; background:linear-gradient(135deg,#0e3a5c,#1e5c2a); overflow:hidden; }
.card-img { width:100%; height:100%; object-fit:cover; }
.card-body { padding:18px 20px 20px; flex:1; display:flex; flex-direction:column; }
.card-title { font-size:17px; font-weight:700; line-height:1.6; margin:0 0 10px; }
.card-title a { color:#0e3a5c; }
.card-meta { font-size:13px; color:#64748b; margin-top:auto; display:flex; gap:12px; flex-wrap:wrap; padding-top:12px; border-top:1px solid #f1f5f9; }

.services-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(155px,1fr)); gap:16px; }
.service-card { background:#fff; border:2px solid #e2e8f0; border-radius:14px; padding:22px 14px; text-align:center; transition:all .25s; display:flex; flex-direction:column; align-items:center; gap:12px; color:#1e293b; }
.service-card:hover { border-color:#1a5490; transform:translateY(-4px); box-shadow:0 12px 32px rgba(14,58,92,.14); }
.service-icon { width:56px; height:56px; background:linear-gradient(135deg,#1a5490,#2d7a3e); color:#fff; border-radius:14px; display:flex; align-items:center; justify-content:center; font-size:24px; box-shadow:0 6px 16px rgba(26,84,144,.25); }
.service-title { font-size:15px; font-weight:700; color:#0e3a5c; margin:0; }

.projects-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(280px,1fr)); gap:24px; }
.project-card { background:#fff; border:2px solid #e2e8f0; border-radius:14px; padding:24px; display:flex; flex-direction:column; gap:14px; }
.project-icon { width:60px; height:60px; background:linear-gradient(135deg,#1a5490,#2d7a3e); color:#fff; border-radius:14px; display:flex; align-items:center; justify-content:center; font-size:28px; }
.project-title { font-size:17px; font-weight:800; color:#0e3a5c; margin:0; }
.project-desc { font-size:14px; color:#64748b; line-height:1.7; margin:0; }

.stats-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:20px; }
.stat-box { background:#fff; padding:30px 20px; border-radius:14px; border:2px solid #e2e8f0; text-align:center; }
.stat-num { font-size:36px; font-weight:900; color:#1a5490; }
.stat-label { color:#64748b; font-weight:600; margin-top:8px; }

.post-single { background:#fff; border-radius:16px; padding:40px; margin:0 0 30px; box-shadow:0 4px 20px rgba(14,58,92,.08); }
.post-title { font-size:32px; font-weight:900; color:#0e3a5c; margin:0 0 18px; line-height:1.4; }
.post-meta { display:flex; flex-wrap:wrap; gap:10px 18px; align-items:center; font-size:14px; color:#64748b; border-bottom:1px solid #e2e8f0; padding-bottom:16px; margin-bottom:24px; }
.post-meta a { background:rgba(45,122,62,.1); color:#2d7a3e; padding:4px 14px; border-radius:20px; font-weight:600; font-size:13px; }
.post-body { font-size:17px; line-height:2; color:#334155; word-wrap:break-word; }
.post-body h2, .post-body h3, .post-body h4 { color:#0e3a5c; margin-top:30px; }
.post-body img { border-radius:10px; margin:18px auto; }
.post-body a { color:#1a5490; text-decoration:underline; }
.post-body ul, .post-body ol { padding-inline-start:24px; margin-bottom:16px; }
.post-body ul li { list-style:disc; }
.post-body ol li { list-style:decimal; }
.post-body blockquote { border-inline-start:4px solid #1a5490; background:#f1f5f9; padding:14px 20px; margin:18px 0; border-radius:8px; }
.post-body strong { font-weight:800; color:#0e3a5c; }
.post-body p { margin:0 0 16px; }

.post-comments { margin-top:40px; padding-top:26px; border-top:2px solid #e2e8f0; }
.post-comments h3 { font-size:20px; font-weight:800; color:#0e3a5c; margin:0 0 18px; }
.comments-cta { text-align:center; padding:36px 24px; background:rgba(26,84,144,.04); border-radius:14px; border:1px dashed #e2e8f0; }
.comments-cta p { font-size:15px; color:#64748b; margin-bottom:18px; }
.comments-btn { display:inline-flex; align-items:center; gap:10px; background:#1a5490; color:#fff; padding:14px 32px; border-radius:28px; font-weight:700; font-size:16px; box-shadow:0 8px 20px rgba(26,84,144,.35); }

.site-footer { background:linear-gradient(135deg,#0e3a5c 0%,#08293f 100%); color:#cbd5e1; margin-top:60px; padding:50px 0 20px; border-top:5px solid #b8935a; }
.footer-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:32px; margin-bottom:32px; }
.footer-col h4 { color:#fff; font-size:16px; font-weight:800; margin:0 0 16px; padding-bottom:10px; border-bottom:2px solid rgba(212,169,97,.3); display:inline-block; }
.footer-col p { font-size:14px; line-height:1.9; margin:0 0 8px; }
.footer-col a { color:#cbd5e1; display:block; padding:6px 0; font-size:14px; }
.footer-col a:hover { color:#d4a961; }
.footer-bottom { text-align:center; padding-top:24px; border-top:1px solid rgba(255,255,255,.1); font-size:13.5px; color:#94a3b8; }

.scroll-top { position:fixed; bottom:24px; left:24px; width:48px; height:48px; border-radius:50%; background:linear-gradient(145deg,#1a5490,#2d7a3e); color:#fff; border:0; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:22px; font-weight:900; box-shadow:0 8px 22px rgba(26,84,144,.45); opacity:0; visibility:hidden; transform:translateY(10px); transition:all .3s; z-index:998; padding:0; }
.scroll-top.show { opacity:1; visibility:visible; transform:translateY(0); }
.scroll-top::before { content:'\2191'; line-height:1; }

.hidden-section { display:none !important; height:0; overflow:hidden; }

#js-blog-area { padding:20px 0; }
.native-blog-area { display:none !important; }

body.item-view .news-head,
body.static_page-view .news-head,
body.is-post .news-head,
body.is-page .news-head { display:none; }

body.item-view .section-alt,
body.static_page-view .section-alt,
body.is-post .section-alt,
body.is-page .section-alt { padding-top:30px; }

/* ═══ DARK MODE ═══ */
body.dark-mode { background:#141413; color:#e8e6e3; color-scheme:dark; }
body.dark-mode h1, body.dark-mode h2, body.dark-mode h3, body.dark-mode h4 { color:#e8e6e3; }
body.dark-mode .site-header { background:linear-gradient(135deg,#08293f 0%,#0e3a5c 55%,#1e5c2a 100%); box-shadow:0 2px 16px rgba(0,0,0,.6); }
body.dark-mode .brand-title { color:#fff !important; }
body.dark-mode .brand-subtitle { color:rgba(255,255,255,.7); }
body.dark-mode .nav-list a { color:#fff !important; }
body.dark-mode .theme-toggle { background:rgba(255,255,255,.15); border-color:rgba(255,255,255,.3); color:#fff; }
/* Search bar in dark mode: dark background */
body.dark-mode .search-form { background:rgba(0,0,0,.35); border-color:rgba(255,255,255,.25); }
body.dark-mode .search-form:focus-within { background:rgba(0,0,0,.5); box-shadow:0 0 0 3px rgba(255,255,255,.15); }
body.dark-mode .search-form input { color:#fff; }
body.dark-mode .search-form input::placeholder { color:rgba(255,255,255,.55); }
body.dark-mode .search-form button { background:#1e5c2a; color:#fff; }
body.dark-mode .search-form button:hover { background:#2d7a3e; }
body.dark-mode .section-alt { background:#1c1c1a; }
body.dark-mode .section-head { border-color:#333; }
body.dark-mode .section-title { color:#e8e6e3 !important; }
body.dark-mode .card { background:#262624; border-color:#3a3a38; }
body.dark-mode .card-title a { color:#e8e6e3; }
body.dark-mode .card-meta { color:#94a3b8; border-color:#3a3a38; }
body.dark-mode .service-card { background:#262624; border-color:#3a3a38; color:#e8e6e3; }
body.dark-mode .service-title { color:#e8e6e3; }
body.dark-mode .project-card { background:#262624; border-color:#3a3a38; }
body.dark-mode .project-title { color:#e8e6e3; }
body.dark-mode .project-desc { color:#94a3b8; }
body.dark-mode .stat-box { background:#262624; border-color:#3a3a38; }
body.dark-mode .stat-num { color:#7db8e8; }
body.dark-mode .stat-label { color:#94a3b8; }
body.dark-mode .post-single { background:#262624; }
body.dark-mode .post-title { color:#e8e6e3; }
body.dark-mode .post-meta { color:#94a3b8; border-color:#3a3a38; }
body.dark-mode .post-body { color:#cbd5e1; }
body.dark-mode .post-body h2, body.dark-mode .post-body h3, body.dark-mode .post-body h4 { color:#e8e6e3; }
body.dark-mode .post-body strong { color:#e8e6e3; }
body.dark-mode .post-body blockquote { background:#2d2d2b; color:#cbd5e1; }
body.dark-mode .post-comments { border-color:#3a3a38; }
body.dark-mode .post-comments h3 { color:#e8e6e3; }
body.dark-mode .comments-cta { background:rgba(125,184,232,.06); border-color:#3a3a38; }
body.dark-mode .loading, body.dark-mode .empty-msg { background:#262624; border-color:#3a3a38; color:#94a3b8; }

/* ═══ MOBILE / TABLET ═══ */
@media (max-width:992px) {
  .header-inner { gap:8px; padding:10px 0; align-items:center; }
  .brand { order:1; margin-inline-end:auto; flex:0 1 auto; min-width:0; }
  .brand-logo-img { width:48px; height:48px; border-radius:10px; }
  .brand-title { font-size:17px; line-height:1.2; }
  .brand-subtitle { display:block; font-size:10.5px; line-height:1.3; margin-top:2px; }
  .nav-toggle { display:flex; align-items:center; justify-content:center; order:2; width:42px; height:42px; flex-shrink:0; }
  .header-tools { display:contents; }
  .theme-toggle { order:3; width:42px; height:42px; flex-shrink:0; }
  .search-form { order:4; flex-basis:100%; width:100%; margin-top:6px; }
  .search-form input { width:100%; flex:1; min-width:0; padding:8px 12px; }
  .search-form button { padding:8px 14px; }
  .main-nav { order:5; display:none; width:100%; flex-basis:100%; margin:8px 0 0; border-top:1px solid rgba(255,255,255,.2); padding-top:8px; }
  .main-nav.open { display:block; }
  .nav-list { flex-direction:column; align-items:stretch; gap:2px; }
  .nav-list a { padding:12px 14px; }

  .section { padding:32px 0; }
  .section-head { margin-bottom:20px; padding-bottom:12px; }
  .section-title { font-size:20px; }
  .section-title::before { height:24px; width:5px; }

  .news-top { grid-template-columns:1fr; height:auto; gap:14px; }
  .news-hero { height:300px; }
  .news-hero .news-item-title { font-size:20px; }
  .news-side-stack { grid-template-rows:auto auto; gap:14px; }
  .news-side { height:200px; }
  .news-grid-4 { grid-template-columns:repeat(2, 1fr); gap:12px; }
  .news-grid-4 .news-item-title { font-size:14px; }

  .post-title { font-size:22px; }
  .post-single { padding:22px; }
  .post-body { font-size:16px; }
  .post-body img { margin:14px auto; }

  .services-grid { grid-template-columns:repeat(3, 1fr); gap:10px; }
  .service-card { padding:16px 10px; gap:8px; }
  .service-icon { width:46px; height:46px; font-size:20px; }
  .service-title { font-size:13px; }

  .projects-grid { grid-template-columns:1fr; gap:14px; }
  .project-card { padding:18px; }

  .stats-grid { grid-template-columns:repeat(2, 1fr); gap:12px; }
  .stat-box { padding:20px 12px; }
  .stat-num { font-size:26px; }
  .stat-label { font-size:13px; }
}
@media (max-width:520px) {
  .brand-logo-img { width:42px; height:42px; }
  .brand-title { font-size:15px; }
  .brand-subtitle { font-size:9.5px; }
  .search-form input { font-size:13px; }
  .news-hero { height:260px; }
  .news-hero .news-item-title { font-size:18px; }
  .news-side { height:170px; }
  .news-grid-4 { grid-template-columns:1fr; }
  .news-grid-4 .news-item { aspect-ratio:16/10; }
  .stats-grid { grid-template-columns:1fr; }
  .post-single { padding:18px; }
  .post-title { font-size:20px; }
}

body.script:
//
(function () {
  var t = document.getElementById('navToggle'); var n = document.getElementById('mainNav');
  if (t && n) { t.addEventListener('click', function () { n.className = n.className.indexOf('open') === -1 ? n.className + ' open' : n.className.replace(' open', ''); }); }
})();
(function () {
  var t = document.getElementById('themeToggle');
  var saved = localStorage.getItem('blogger-theme') || 'light';
  if (saved === 'dark') { document.body.classList.add('dark-mode'); }
  if (t) { t.addEventListener('click', function () { document.body.classList.toggle('dark-mode'); localStorage.setItem('blogger-theme', document.body.classList.contains('dark-mode') ? 'dark' : 'light'); }); }
})();
//

//
function upgradeBloggerUrl(url) {
  if (!url) return '';
  return url.replace(/\/(s\d+|w\d+-h\d+[^\/]*)\//, '/w1200-h800-c/');
}
function thumbUpgrade(entry) {
  var content = '';
  if (entry.content && entry.content.$t) content = entry.content.$t;
  else if (entry.summary && entry.summary.$t) content = entry.summary.$t;
  if (content) {
    var m = content.match(/(?:youtube(?:-nocookie)?\.com\/(?:embed\/|watch\?v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
    if (m && m[1]) return 'https://i.ytimg.com/vi/' + m[1] + '/maxresdefault.jpg';
    var imgMatch = content.match(/<img[^>]+src\s*=\s*["']([^"']+)["']/i);
    if (imgMatch && imgMatch[1]) {
      var src = imgMatch[1].replace(/&amp;/g, '&');
      if (src.indexOf('blogger.googleusercontent.com') !== -1 || src.indexOf('bp.blogspot.com') !== -1) return upgradeBloggerUrl(src);
      return src;
    }
  }
  if (!entry.media$thumbnail || !entry.media$thumbnail.url) return '';
  var url = entry.media$thumbnail.url;
  if (url.indexOf('ytimg.com') !== -1) return url.replace(/\/[a-z]*default\.jpg/, '/maxresdefault.jpg');
  return upgradeBloggerUrl(url);
}
function getLink(entry) {
  if (!entry.link) return '#';
  for (var i = 0; i < entry.link.length; i++) { if (entry.link[i].rel === 'alternate') return entry.link[i].href; }
  return '#';
}
function formatDate(iso) {
  if (!iso) return '';
  var d = new Date(iso);
  if (isNaN(d)) return iso.substring(0,10);
  var months = ['يناير','فبراير','مارس','أبريل','ماي','يونيو','يوليوز','غشت','شتنبر','أكتوبر','نونبر','دجنبر'];
  return d.getDate() + ' ' + months[d.getMonth()] + '، ' + d.getFullYear();
}
function esc(s) { return String(s).replace(/[&<>"']/g, function(c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function fetchFeed(url, cb, errCb) {
  var cbName = 'jscb_' + Math.random().toString(36).substr(2, 9);
  var timeout = setTimeout(function() { if (window[cbName]) { window[cbName] = null; if (errCb) errCb(); } }, 10000);
  window[cbName] = function(json) {
    clearTimeout(timeout);
    var entries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
    cb(entries);
    try { delete window[cbName]; } catch(e) { window[cbName] = null; }
  };
  var s = document.createElement('script');
  s.src = url + (url.indexOf('?') === -1 ? '?' : '&') + 'alt=json-in-script&callback=' + cbName;
  s.async = true;
  s.onerror = function() { clearTimeout(timeout); if (errCb) errCb(); };
  document.body.appendChild(s);
}
function renderPostContent(area, match) {
  var title = match.title ? match.title.$t : '';
  var content = match.content ? match.content.$t : (match.summary ? match.summary.$t : '');
  var date = formatDate(match.published ? match.published.$t : '');
  var labelsHtml = '', i;
  if (match.category) {
    for (i = 0; i < match.category.length; i++) {
      labelsHtml += '<a href="/search/label/' + encodeURIComponent(match.category[i].term) + '">' + esc(match.category[i].term) + '</a>';
    }
  }
  var postId = '';
  if (match.id && match.id.$t) {
    var m = match.id.$t.match(/post-(\d+)/);
    if (m) postId = m[1];
  }
  var commentsHtml = '';
  if (postId && typeof BLOG_ID !== 'undefined' && BLOG_ID) {
    commentsHtml = '<div class="post-comments"><h3>التعليقات</h3><div class="comments-cta"><p>شاركنا رأيك وتعليقك على هذه المشاركة</p><a class="comments-btn" target="_blank" rel="noopener" href="https://www.blogger.com/comment.g?blogID=' + BLOG_ID + '&postID=' + postId + '">اكتب تعليقًا</a></div></div>';
  }
  area.innerHTML = '<article class="post-single"><h1 class="post-title">' + esc(title) + '</h1><div class="post-meta"><span>\uD83D\uDCC5 ' + date + '</span>' + labelsHtml + '</div><div class="post-body">' + content + '</div>' + commentsHtml + '</article>';
  if (title) document.title = title + ' | جماعة إنشادن';
}
