//
(function () {
  var area = document.getElementById('js-blog-area');
  if (!area) return;
  var path = window.location.pathname;
  var search = window.location.search;

  function newsItem(entry, extraClass) {
    var link = getLink(entry);
    var title = entry.title ? entry.title.$t : '';
    var thumb = thumbUpgrade(entry);
    var date = formatDate(entry.published ? entry.published.$t : '');
    var cls = 'news-item ' + (extraClass || '') + (thumb ? '' : ' no-image');
    var bgHtml = thumb ? '<img class="news-item-bg" src="' + thumb + '" alt="' + esc(title) + '" loading="lazy" onerror="this.style.display=&quot;none&quot;;"/>' : '';
    return '<a class="' + cls + '" href="' + link + '" title="' + esc(title) + '">' +
      bgHtml +
      '<div class="news-item-overlay">' +
        '<h3 class="news-item-title">' + esc(title) + '</h3>' +
        '<span class="news-item-date">\uD83D\uDCC5 ' + date + '</span>' +
      '</div>' +
    '</a>';
  }

  function cardItem(entry) {
    var link = getLink(entry);
    var title = entry.title ? entry.title.$t : '';
    var thumb = thumbUpgrade(entry);
    var date = formatDate(entry.published ? entry.published.$t : '');
    var thumbHtml = thumb ? '<a class="card-thumb" href="' + link + '"><img class="card-img" src="' + thumb + '" alt="' + esc(title) + '" loading="lazy"/></a>' : '';
    return '<article class="card">' + thumbHtml +
      '<div class="card-body">' +
        '<h3 class="card-title"><a href="' + link + '">' + esc(title) + '</a></h3>' +
        '<div class="card-meta"><span>\uD83D\uDCC5 ' + date + '</span></div>' +
      '</div>' +
    '</article>';
  }

  function renderMagazine(entries) {
    if (!entries.length) { area.innerHTML = '<p class="empty-msg">لا توجد مشاركات بعد.</p>'; return; }
    var hero = entries[0], side1 = entries[1], side2 = entries[2], grid = entries.slice(3, 7);
    var html = '<div class="news-magazine">';
    html += '<div class="news-top">';
    html += newsItem(hero, 'news-hero');
    html += '<div class="news-side-stack">';
    if (side1) html += newsItem(side1, 'news-side');
    if (side2) html += newsItem(side2, 'news-side');
    html += '</div></div>';
    if (grid.length) {
      html += '<div class="news-grid-4">';
      for (var i = 0; i < grid.length; i++) html += newsItem(grid[i], '');
      html += '</div>';
    }
    html += '</div>';
    area.innerHTML = html;
  }

  var isPostPage = /\/\d{4}\/\d{2}\/[^\/]+\.html$/.test(path.toLowerCase());
  var isStaticPage = path.indexOf('/p/') === 0 || document.body.className.indexOf('static_page-view') !== -1;

  if (isPostPage || isStaticPage) {
    var cls = isPostPage ? 'item-view' : 'static_page-view';
    if (document.body.className.indexOf(cls) === -1) document.body.className += ' ' + cls;
    area.innerHTML = '<div class="loading">جارٍ تحميل الصفحة...</div>';

    var settled = false;
    function settle() { settled = true; }
    function fail() { if (!settled) { settle(); area.innerHTML = '<p class="empty-msg">تعذّر تحميل المحتوى.</p>'; } }

    var postPath = path.split('?')[0];
    var primaryUrl = '/feeds/posts/default?path=' + encodeURIComponent(postPath) + '&max-results=1';

    fetchFeed(primaryUrl, function (entries) {
      if (entries.length) { settle(); renderPostContent(area, entries[0]); return; }
      matchByUrl();
    }, function () { matchByUrl(); });

    function matchByUrl() {
      if (settled) return;
      fetchFeed('/feeds/pages/default?max-results=50', function (pageEntries) {
        var fullUrl = window.location.href.split('?')[0].split('#')[0].replace(/\/$/, '');
        for (var i = 0; i < pageEntries.length; i++) {
          var l = getLink(pageEntries[i]).split('?')[0].split('#')[0].replace(/\/$/, '');
          if (l === fullUrl) { settle(); renderPostContent(area, pageEntries[i]); return; }
        }
        tryPostsFeed();
      }, tryPostsFeed);
    }

    function tryPostsFeed() {
      if (settled) return;
      fetchFeed('/feeds/posts/default?max-results=150', function (entries) {
        if (settled) return;
        var fullUrl = window.location.href.split('?')[0].split('#')[0].replace(/\/$/, '');
        for (var j = 0; j < entries.length; j++) {
          var l2 = getLink(entries[j]).split('?')[0].split('#')[0].replace(/\/$/, '');
          if (l2 === fullUrl) { settle(); renderPostContent(area, entries[j]); return; }
        }
        fail();
      }, fail);
    }
    return;
  }

  function showEmpty(msg) { area.innerHTML = '<p class="empty-msg">' + msg + '</p>'; }

  if (path.indexOf('/search/label/') !== -1) {
    var labelName = decodeURIComponent((path.split('/search/label/')[1] || '').split('?')[0].split('#')[0]);
    area.innerHTML = '<div class="loading">جارٍ تحميل المشاركات...</div>';
    var variations = [labelName];
    if (labelName.indexOf('ال') === 0) variations.push(labelName.substring(2));
    else variations.push('ال' + labelName);
    var idx = 0;
    (function tryLabel() {
      if (idx >= variations.length) {
        fetchFeed('/feeds/posts/default?max-results=24', function(entries) {
          if (!entries.length) { showEmpty('لا توجد مشاركات بعد.'); return; }
          area.innerHTML = '<div class="cards-grid">' + entries.map(cardItem).join('') + '</div>';
        }, function() { showEmpty('تعذّر تحميل المشاركات.'); });
        return;
      }
      var v = variations[idx++];
      fetchFeed('/feeds/posts/default/-/' + encodeURIComponent(v) + '?max-results=24', function(entries) {
        if (!entries.length) { tryLabel(); return; }
        area.innerHTML = '<div class="cards-grid">' + entries.map(cardItem).join('') + '</div>';
      }, function() { tryLabel(); });
    })();
    return;
  }

  if (path.indexOf('/search') !== -1 && search.indexOf('q=') !== -1) {
    var q = decodeURIComponent(search.split('q=')[1].split('&')[0].replace(/\+/g, ' '));
    area.innerHTML = '<div class="loading">جارٍ البحث...</div>';
    fetchFeed('/feeds/posts/default?q=' + encodeURIComponent(q) + '&max-results=24', function(entries) {
      if (!entries.length) { showEmpty('لا توجد نتائج لبحثك.'); return; }
      area.innerHTML = '<div class="cards-grid">' + entries.map(cardItem).join('') + '</div>';
    }, function() { showEmpty('تعذّر البحث.'); });
    return;
  }

  area.innerHTML = '<div class="loading">جارٍ التحميل...</div>';
  fetchFeed('/feeds/posts/default?max-results=7', function(entries) {
    renderMagazine(entries);
  }, function() { showEmpty('تعذّر تحميل المشاركات.'); });
})();
