(function () {
  var btn = document.createElement('button');
  btn.className = 'scroll-top'; btn.type = 'button';
  btn.setAttribute('aria-label', 'العودة إلى الأعلى');
  document.body.appendChild(btn);
  function onScroll() { btn.classList.toggle('show', window.scrollY > 300); }
  var ticking = false;
  window.addEventListener('scroll', function () {
    if (!ticking) { window.requestAnimationFrame(function () { onScroll(); ticking = false; }); ticking = true; });
  }, { passive: true });
  btn.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  onScroll();
})();
